using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Drawing;using System.Drawing.Drawing2D;using System.Windows.Forms;using System.ComponentModel;using System.Threading;
namespace DashCanvas {
public partial class MainForm {
 void StartLoad(string path){if(busy)return;busy=true;Enabled=false;Status("Scanning all game assets...",false);var worker=new BackgroundWorker{WorkerReportsProgress=true};worker.DoWork+=delegate(object sender,DoWorkEventArgs e){var game=new Game(path);var catalog=new AssetCatalog(game.Resources,s=>worker.ReportProgress(0,s));e.Result=new object[]{game,catalog};};worker.ProgressChanged+=delegate(object sender,ProgressChangedEventArgs e){Status(e.UserState.ToString(),false);};worker.RunWorkerCompleted+=delegate(object sender,RunWorkerCompletedEventArgs e){busy=false;Enabled=true;if(e.Error!=null)Safe(delegate{throw e.Error;});else Safe(delegate{var a=(object[])e.Result;Bind((Game)a[0],(AssetCatalog)a[1]);});worker.Dispose();};worker.RunWorkerAsync();}
 public void LoadGame(string path){Bind(new Game(path),new AssetCatalog(Path.Combine(path,"Resources")));}
 void Bind(Game game,AssetCatalog catalog){draftKey=null;Game=game;Catalog=catalog;if(resources!=null)resources.Dispose();resources=Game.OpenResources();if(activeResources!=null)activeResources.Dispose();activeResources=Game.OpenResources(true);edited=new HashSet<string>(Game.Project().Edits.Select(x=>x.Key));Directory.CreateDirectory(Path.GetDirectoryName(pref));File.WriteAllText(pref,game.Root);location.Text="CONNECTED / "+game.Root+"   ·   "+catalog.Items.Count.ToString("N0")+" assets";Filter();LoadMenu();var first=Catalog.Items.FirstOrDefault(a=>a.Name=="GJ_createBtn_001.png"&&a.Kind=="sprite");if(first!=null)ChooseAsset(first);Status("Ready. Choose an asset, pick a picture, and apply your design. Close the game before applying."+(Catalog.Issues.Count>0?" Could not index "+Catalog.Issues.Count+" files; see data/catalog-issues.txt.":""),true);File.WriteAllLines(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"data","catalog-issues.txt"),Catalog.Issues);UpdateButtons();}
 static readonly string[] Home={"GJ_logo_001.png","GJ_profileButton_001.png","GJ_playBtn_001.png","GJ_searchBtn_001.png","GJ_garageBtn_001.png","GJ_creatorBtn_001.png"};
 void Filter(){if(Catalog==null)return;string cat=category.Text,q=search.Text.Trim().ToLowerInvariant();IEnumerable<Asset> list=Catalog.Items;if(q.Length>0)list=list.Where(a=>q.Split(new[]{' '},StringSplitOptions.RemoveEmptyEntries).All(word=>a.SearchText.Contains(word)));else if(cat=="Main Menu")list=list.Where(a=>Home.Contains(a.Name)||new[]{"GJ_optionsBtn_001.png","GJ_achBtn_001.png","GJ_statsBtn_001.png","GJ_dailyRewardBtn_001.png"}.Contains(a.Name)||a.Name=="game_bg_01_001.png");else if(cat=="My Changes")list=list.Where(a=>edited.Contains(a.Key));else if(cat!="All Assets")list=list.Where(a=>a.Category==cat);var order=cat=="Level Browser"?AssetNames.BrowserOrder:Home;filtered=list.OrderBy(a=>Array.IndexOf(order,a.Name)<0?999:Array.IndexOf(order,a.Name)).ThenBy(a=>a.Title).ToList();page=0;RenderPage();}
 void RenderPage(){loading=true;gallery.BeginUpdate();var sheets=new Dictionary<string,Bitmap>();try{gallery.Items.Clear();thumbnails.Images.Clear();var handle=thumbnails.Handle;foreach(var a in filtered.Skip(page*PageSize).Take(PageSize)){
   string v=a.Variants.OrderBy(AssetCatalog.Quality).First();Bitmap sheet;if(!sheets.TryGetValue(v,out sheet)){sheet=Pictures.Load(Path.Combine(Game.Resources,v));sheets[v]=sheet;}
   using(var im=a.Kind=="image"?new Bitmap(sheet):Catalog.Frames[v].First(f=>f.Name==a.FrameName).Extract(sheet))using(var thumb=new Bitmap(116,80))using(var g=Graphics.FromImage(thumb)){g.Clear(Card);float scale=Math.Min(108f/im.Width,74f/im.Height);int w=Math.Max(1,(int)(im.Width*scale)),h=Math.Max(1,(int)(im.Height*scale));g.InterpolationMode=InterpolationMode.HighQualityBicubic;g.DrawImage(im,new Rectangle((116-w)/2,(80-h)/2,w,h));thumbnails.Images.Add(a.Key,thumb);}
   string name=a.Title;if(name.Length>31)name=name.Substring(0,29)+"…";gallery.Items.Add(new ListViewItem((edited.Contains(a.Key)?"✓ ":"")+name,a.Key){Tag=a,ToolTipText=a.Title+"\n"+a.Group});
  }double dpi;using(var g=CreateGraphics())dpi=g.DpiX/96;gallery.TileSize=new Size((int)(143*dpi),(int)(130*dpi));
 }finally{foreach(var s in sheets.Values)s.Dispose();gallery.EndUpdate();loading=false;}count.Text=filtered.Count==0?"No matching assets":"Showing "+(page*PageSize+1)+"–"+Math.Min((page+1)*PageSize,filtered.Count)+" of "+filtered.Count;previous.Enabled=page>0;next.Enabled=(page+1)*PageSize<filtered.Count;}
 public void ChooseAsset(Asset asset){Selected=asset;if(original!=null)original.Dispose();string v=asset.Variants.OrderByDescending(AssetCatalog.Quality).First();original=Game.AssetOriginal(asset,v,resources);current.Set(Game.AssetCurrent(asset,activeResources));if(draftSource==null||draftKey!=asset.Key){if(draftSource!=null)draftSource.Dispose();draftSource=new Bitmap(current.Image.Width,current.Image.Height,System.Drawing.Imaging.PixelFormat.Format32bppArgb);Pictures.CopyExact(current.Image,draftSource,0,0);draftKey=asset.Key;}gallery.Invalidate();title.Text=asset.Title+(edited.Contains(asset.Key)?"  ✓":"");fileInfo.Text=asset.Category+"  /  "+asset.Variants.Count+" quality sizes  /  "+original.Width+" x "+original.Height+" px";loading=true;symbol.SelectedItem=asset.Symbol;position.SelectedIndex=asset.Symbol=="Original badge"?1:0;shape.SelectedItem=asset.Kind=="image"?"Rectangle":"Original shape";border.Checked=asset.Kind!="image";loading=false;UpdateStyleSelection();RefreshIdeas();RefreshPreview();UpdateButtons();menu.SelectedName=browser.SelectedName=asset.Name;menu.Invalidate();browser.Invalidate();}
 public void LoadPicture(string path){Safe(delegate{var im=Pictures.Load(path);if(photo!=null)photo.Dispose();photo=im;pictureInfo.Text=Path.GetFileName(path)+"  ·  "+im.Width+"×"+im.Height;AutoFocus();RefreshIdeas();UpdateButtons();Status("Picture ready. Choose a style or adjust the shape and symbol, then apply.",true);});}
 void AutoFocus(){if(photo==null)return;var p=Pictures.Analyze(photo);loading=true;focusX.Value=Math.Max(0,Math.Min(100,(int)(p.X*100)));focusY.Value=Math.Max(0,Math.Min(100,(int)(p.Y*100)));loading=false;RefreshPreview();}
 Design Options(){return AddLayerOptions(AddStyleOptions(new Design{Shape=shape.Text,Symbol=symbol.Text,SymbolPosition=position.SelectedIndex,Border=border.Checked,Fit=new FitOptions{Mode=fit.SelectedIndex,X=focusX.Value/100f,Y=focusY.Value/100f,Brightness=brightness.Value/100f,Gray=gray.Checked,Transparent=true}})); }
 Design Idea(int n){var d=Options();d.Shape=new[]{"Original shape","Rectangle","Circle","Rounded","Diamond","Hexagon"}[n];d.Symbol=n==1?"None":Selected.Symbol;d.SymbolPosition=n==3?1:Selected.Symbol=="Original badge"?1:0;d.Border=n>1;return d;}
 void ApplyIdea(int n){if(Selected==null)return;var d=Idea(n);loading=true;shape.SelectedItem=d.Shape;symbol.SelectedItem=d.Symbol;position.SelectedIndex=d.SymbolPosition;border.Checked=d.Border;loading=false;RefreshPreview();}
 void RefreshIdeas(){for(int i=0;i<ideas.Length;i++){if(ideas[i].Image!=null){ideas[i].Image.Dispose();ideas[i].Image=null;}if(original==null)continue;using(var baseImage=Small(original,110))using(var im=Designer.Render(photo??draftSource??current.Image,baseImage,Idea(i))){var b=new Bitmap(100,65);using(var g=Graphics.FromImage(b)){g.Clear(Card);float s=Math.Min(96f/im.Width,61f/im.Height);int w=Math.Max(1,(int)(im.Width*s)),h=Math.Max(1,(int)(im.Height*s));g.DrawImage(im,(100-w)/2,(65-h)/2,w,h);}ideas[i].Image=b;}}}
 static Bitmap Small(Bitmap source,int max){float scale=Math.Min(1,(float)max/Math.Max(source.Width,source.Height));return new Bitmap(source,Math.Max(1,(int)(source.Width*scale)),Math.Max(1,(int)(source.Height*scale)));}
 void RefreshPreview(){if(loading)return;RefreshLayerControls();focusX.Enabled=focusY.Enabled=fit.SelectedIndex==0;if(original==null){preview.Set(null);menu.Pending=browser.Pending=null;menu.Invalidate();browser.Invalidate();return;}Safe(delegate{using(var mask=Small(original,640))preview.Set(Designer.Render(photo??draftSource??current.Image,mask,Options()));menu.Pending=browser.Pending=preview.Image;menu.Invalidate();browser.Invalidate();});}
 void LoadMenu(){menu.Clear();browser.Clear();foreach(var name in Home.Concat(new[]{"difficulty_01_btn_001.png","difficulty_03_btn_001.png","difficulty_08_btn_001.png","difficulty_10_btn_001.png"}).Concat(AssetNames.BrowserOrder).Distinct()){var asset=Catalog.Items.FirstOrDefault(a=>a.Name==name&&a.Kind=="sprite");if(asset!=null)using(var im=Game.AssetCurrent(asset,activeResources)){if(AssetNames.BrowserOrder.Contains(name))browser.Images[name]=Small(im,600);menu.Images[name]=Small(im,600);}}menu.Invalidate();browser.Invalidate();}
 void AfterWrite(){edited=new HashSet<string>(Game.Project().Edits.Select(x=>x.Key));if(resources!=null)resources.Dispose();resources=Game.OpenResources();if(activeResources!=null)activeResources.Dispose();activeResources=Game.OpenResources(true);ChooseAsset(Selected);RenderPage();LoadMenu();UpdateButtons();}
 void UpdateButtons(){bool ready=Game!=null&&Selected!=null;apply.Enabled=ready&&Game.HasLoader;restore.Enabled=ready&&edited.Contains(Selected.Key);export.Enabled=Game!=null&&(edited.Count>0||Selected!=null);UpdateFontButtons();}
}
static class Program {
 [STAThread]static int Main(string[] args){bool created;using(var mutex=new Mutex(true,@"Local\DashCanvas.BackgroundStudio",out created)){if(!created){MessageBox.Show("DashCanvas is already open. Close it before opening the updated version.");return 0;}Thread.CurrentThread.CurrentCulture=System.Globalization.CultureInfo.GetCultureInfo("en-US");Thread.CurrentThread.CurrentUICulture=System.Globalization.CultureInfo.GetCultureInfo("en-US");Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);try{Application.Run(new MainForm(args.Length>0?args[0]:null));return 0;}catch(Exception e){MessageBox.Show(e.Message,"DashCanvas");return 1;}}}
}
}
